package ai.arena.villagame;

import android.content.Context;
import android.media.AudioManager;
import android.media.MediaPlayer;
import android.media.SoundPool;

/**
 * Wind, footsteps and a pickup chime. All four clips are generated by
 * `tools/game_audio.py` (numpy, no samples, no downloads) and shipped in res/raw, which
 * keeps the whole soundtrack under 300 kB.
 */
public class Audio {

    private final Context ctx;
    private SoundPool pool;
    private int step = 0, chime = 0, click = 0;
    private MediaPlayer wind;
    private boolean ready = false;
    private boolean muted = false;

    public Audio(Context ctx) {
        this.ctx = ctx;
        try {
            pool = new SoundPool(4, AudioManager.STREAM_MUSIC, 0);
            pool.setOnLoadCompleteListener(new SoundPool.OnLoadCompleteListener() {
                @Override
                public void onLoadComplete(SoundPool sp, int id, int status) {
                    ready = status == 0;
                }
            });
            step = pool.load(ctx, R.raw.step, 1);
            chime = pool.load(ctx, R.raw.chime, 1);
            click = pool.load(ctx, R.raw.step, 1);
        } catch (Throwable t) {
            pool = null;
        }
    }

    public void resume() {
        if (muted) return;
        try {
            if (wind == null) {
                wind = MediaPlayer.create(ctx, R.raw.wind);
                if (wind != null) {
                    wind.setLooping(true);
                    wind.setVolume(0.30f, 0.30f);
                }
            }
            if (wind != null && !wind.isPlaying()) wind.start();
        } catch (Throwable ignored) {
        }
    }

    public void pause() {
        try {
            if (wind != null && wind.isPlaying()) wind.pause();
        } catch (Throwable ignored) {
        }
    }

    public void footstep(float speed) {
        play(step, 0.28f + 0.30f * speed, 0.92f + 0.16f * (float) Math.random());
    }

    public void pickup() {
        play(chime, 0.85f, 1.0f);
    }

    public void click() {
        play(click, 0.5f, 1.25f);
    }

    private void play(int id, float vol, float rate) {
        if (pool == null || !ready || id == 0 || muted) return;
        try {
            int stream = pool.play(id, vol, vol, 1, 0, rate);
            if (stream == 0) {
                // first play before the sample finished loading: harmless, drop it
            }
        } catch (Throwable ignored) {
        }
    }

    public void release() {
        try {
            if (wind != null) {
                wind.release();
                wind = null;
            }
            if (pool != null) {
                pool.release();
                pool = null;
            }
        } catch (Throwable ignored) {
        }
    }
}
